INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 14, 'theory', 'Квиз: HTML — изображения, медиа и таблицы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 0, 'Что нужно написать в alt у картинки, которая только украшает страницу?', '["Слово «картинка»","Пустую строку: атрибут остаётся, но значение пустое","Имя файла","Атрибут alt нужно убрать совсем"]', 1, 'Пустой alt говорит скринридеру пропустить картинку. Если атрибута нет вовсе, многие программы зачитают имя файла вслух, а валидатор сообщит об ошибке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 1, 'Зачем указывать у img атрибуты width и height с настоящими размерами файла?', '["Чтобы браузер растянул картинку до этих размеров","Чтобы файл грузился быстрее","Чтобы тег считался валидным","Чтобы браузер заранее вычислил пропорции и зарезервировал место, а вёрстка не прыгала"]', 3, 'Из width и height браузер получает соотношение сторон ещё до загрузки файла и оставляет под картинку место. Без этого содержимое ниже сдвигается, а метрика CLS растёт. Реальный размер на экране потом задают стили.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 2, 'Какую роль играет sizes рядом с srcset?', '["Сообщает браузеру, какую ширину картинка займёт в вёрстке, чтобы он выбрал подходящий файл","Ограничивает размер файла в килобайтах","Меняет отображаемый размер картинки","Выбирает формат файла: avif или webp"]', 0, 'srcset перечисляет файлы и их ширину в пикселях, sizes описывает слот в вёрстке. Зная слот, плотность экрана и сеть, браузер сам выбирает файл. Отображаемую ширину по-прежнему задаёт CSS, а формат выбирается тегом picture.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 3, 'Что даёт ячейке заголовка таблицы атрибут scope="col"?', '["Окрашивает шапку таблицы","Объединяет все ячейки столбца","Связывает заголовок со столбцом: скринридер прочитает число вместе с названием столбца","Прячет заголовок от скринридера"]', 2, 'scope говорит, к чему относится заголовок: col — к столбцу, row — к строке. Поэтому на ячейке со значением скринридер объявит и значение, и его заголовки. Объединяют ячейки colspan и rowspan, а оформлением занимается CSS.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 4, 'Как ведёт себя iframe с атрибутом sandbox без значений?', '["Разрешает всё, как у обычного фрейма","Запрещает скрипты, формы и переходы внутри фрейма; нужные возможности разрешают по одному","Ничего не меняет: у sandbox обязателен список значений","Откладывает загрузку фрейма до прокрутки"]', 1, 'Пустой sandbox включает самый строгий режим, а значения вроде allow-scripts или allow-forms по одному возвращают отдельные права. Отложенную загрузку включает loading=lazy, а имя для скринридера задаёт title.');
